  • Legacy: {"from":{"phoneNumber":"..."},"to":{"phoneNumber":"..."},"duration":45,"recording":{"contentUri":"..."}}
  • Nested: {"call":{"from":"+14805551212","to":"+16028874400","duration":45,"direction":"inbound","recording_url":"..."}}
